using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using Great.Parts.Cel.Eng.Tests.Support;
using Great.Parts.Cel.Eng.Unicode;
using Xunit;
using GeneratorProgram = Great.Parts.Cel.Eng.Unicode.Program;

namespace Great.Parts.Cel.Eng.Tests.Unicode;

// The form of the generated files and the invocation of the generator (docs/design/unicode-tables.md, "The form of the output").
public sealed class OutputTests
{
    private static readonly string[] FileNames = ["UnicodeTables.Folding.g.cs", "UnicodeTables.Names.g.cs", "UnicodeTables.Ranges.g.cs"];

    private static Func<Uri, byte[]> NoNetwork => address => throw new IOException("the generator went to the network for " + address);

    [Fact]
    public static void Output_IsThreeFilesWithTheMarkerTheVersionAndTheThreeChecksums()
    {
        UcdInputs inputs = Excerpts.Inputs();

        var files = TablesWriter.Write(Excerpts.Model());

        Assert.Equal(FileNames, files.Select(file => file.Name));
        foreach (GeneratedFile file in files)
        {
            Assert.StartsWith("// <auto-generated>\n// Written by eng/unicode from the Unicode Character Database 17.0.0:\n", file.Text, StringComparison.Ordinal);
            Assert.Contains("\n// </auto-generated>\n", file.Text, StringComparison.Ordinal);
            foreach (UcdFile input in inputs.Files)
            {
                Assert.Contains($"//   {input.Name,-16} {input.Sha256}\n", file.Text, StringComparison.Ordinal);
            }

            Assert.Contains("namespace Great.Parts.Cel.Library.Unicode;\n\ninternal static partial class UnicodeTables\n{\n", file.Text, StringComparison.Ordinal);
        }
    }

    [Fact]
    public static void Output_HasLineFeedsOnlyOneFinalLineFeedAndNothingThatVaries()
    {
        foreach (GeneratedFile file in TablesWriter.Write(Excerpts.Model()))
        {
            Assert.DoesNotContain("\r", file.Text, StringComparison.Ordinal);
            Assert.EndsWith("}\n", file.Text, StringComparison.Ordinal);
            Assert.DoesNotContain("\n\n\n", file.Text, StringComparison.Ordinal);
            Assert.DoesNotContain("\t", file.Text, StringComparison.Ordinal);
            Assert.All(file.Text.Split('\n'), line => Assert.Equal(line.TrimEnd(), line));
            Assert.DoesNotMatch(@"20[0-9]{2}-[0-9]{2}-[0-9]{2}", file.Text);
        }
    }

    [Fact]
    public static void Numbers_AreHexadecimalOfSixDigitsAndAtMostEightToALine()
    {
        foreach (GeneratedFile file in TablesWriter.Write(Excerpts.Model()).Where(file => !file.Name.Contains("Names", StringComparison.Ordinal)))
        {
            foreach (string line in file.Text.Split('\n').Where(line => line.Contains("0x", StringComparison.Ordinal)))
            {
                string[] values = [.. line.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)];
                Assert.InRange(values.Length, 1, 8);
                Assert.All(values, value => Assert.Matches("^0x[0-9A-F]{6}$", value));
            }
        }
    }

    [Fact]
    public static void RangeFile_HasTheTableCountTheStartsAndTheRangesOfEachTable()
    {
        TableModel model = Excerpts.Model();

        string text = TablesWriter.Write(model).Single(file => file.Name == TablesWriter.RangesFile).Text;

        Assert.Contains($"internal const int TableCount = {model.Tables.Count};", text, StringComparison.Ordinal);
        for (int number = 0; number < model.Tables.Count; number++)
        {
            Assert.Contains($"        // {number} {model.Tables[number].Name}, {model.Tables[number].Ranges.Count} ranges\n", text, StringComparison.Ordinal);
        }

        int startsAt = text.IndexOf("TableStarts =>", StringComparison.Ordinal);
        int dataAt = text.IndexOf("RangeData =>", StringComparison.Ordinal);
        int[] starts = Values(text[startsAt..dataAt]);
        int[] data = Values(text[dataAt..]);
        Assert.Equal(model.Tables.Count + 1, starts.Length);
        Assert.Equal(model.Tables.SelectMany(table => table.Ranges.Pairs.ToArray()), data);
        int offset = 0;
        for (int number = 0; number < model.Tables.Count; number++)
        {
            Assert.Equal(offset, starts[number]);
            offset += model.Tables[number].Ranges.Pairs.Length;
        }

        Assert.Equal(offset, starts[^1]);
    }

    // The values of the lines of an array, comments left out.
    private static int[] Values(string text) =>
        [.. text.Split('\n')
            .Where(line => line.StartsWith("        0x", StringComparison.Ordinal))
            .SelectMany(line => line.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            .Select(value => int.Parse(value[2..], NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture))];

    [Fact]
    public static void NamesFile_IsASwitchOnTheCanonicalNameWithoutADictionary()
    {
        string text = TablesWriter.Write(Excerpts.Model()).Single(file => file.Name == TablesWriter.NamesFile).Text;

        Assert.Contains("internal static bool TryFindTable(ReadOnlySpan<char> canonicalName, out TableName name)", text, StringComparison.Ordinal);
        Assert.Contains("switch (canonicalName)", text, StringComparison.Ordinal);
        Assert.Contains("case \"Olditalic\":\n", text, StringComparison.Ordinal);
        Assert.Contains("case \"Assigned\":\n                name = new TableName(3, 3, true);\n                return true;\n", text, StringComparison.Ordinal);
        Assert.DoesNotContain("Dictionary", text, StringComparison.Ordinal);
        Assert.DoesNotContain("case \"Any\"", text, StringComparison.Ordinal);
        Assert.DoesNotContain("case \"Ascii\"", text, StringComparison.Ordinal);
        Assert.EndsWith("            default:\n                name = default;\n                return false;\n        }\n    }\n}\n", text, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("tr-TR")]
    [InlineData("ar-SA")]
    [InlineData("de-DE")]
    [InlineData("th-TH")]
    public static void Output_IsTheSameInAnyCultureOfTheProcess(string culture)
    {
        var expected = TablesWriter.Write(Excerpts.Model());
        CultureInfo before = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = new CultureInfo(culture);
            CultureInfo.CurrentUICulture = new CultureInfo(culture);

            var actual = TablesWriter.Write(Excerpts.Model());

            Assert.Equal(expected, actual);
        }
        finally
        {
            CultureInfo.CurrentCulture = before;
            CultureInfo.CurrentUICulture = before;
        }
    }

    [Fact]
    public static void TwoRunsInTwoDirectories_GiveTheSameBytes()
    {
        using TempDirectory first = Excerpts.Repository(withDownloads: true);
        using TempDirectory second = Excerpts.Repository(withDownloads: true);

        Assert.Equal(0, GeneratorProgram.Run([], first.Path, TextWriter.Null, TextWriter.Null, NoNetwork));
        Assert.Equal(0, GeneratorProgram.Run([], second.Path, TextWriter.Null, TextWriter.Null, NoNetwork));

        foreach (string name in FileNames)
        {
            Assert.Equal(
                File.ReadAllBytes(Path.Combine(first.Path, GeneratorProgram.OutputDirectory, name)),
                File.ReadAllBytes(Path.Combine(second.Path, GeneratorProgram.OutputDirectory, name)));
        }
    }

    [Fact]
    public static void Run_WritesTheThreeFilesWithoutABomAndNamesEachOne()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: true);
        using StringWriter output = new();

        int exitCode = GeneratorProgram.Run([], root.Path, output, TextWriter.Null, NoNetwork);

        Assert.Equal(0, exitCode);
        Assert.Equal(
            string.Concat(FileNames.Select(name => $"eng/unicode: wrote {GeneratorProgram.OutputDirectory}/{name}{Environment.NewLine}")),
            output.ToString());
        foreach (string name in FileNames)
        {
            byte[] bytes = File.ReadAllBytes(Path.Combine(root.Path, GeneratorProgram.OutputDirectory, name));
            Assert.NotEqual(0xEF, bytes[0]);
            Assert.Equal("// <auto-generated>", Encoding.UTF8.GetString(bytes, 0, 19));
        }
    }

    [Fact]
    public static void Check_SucceedsOnTheOutputAndFailsWithExitCode1OnAFileThatDiffersOrIsMissing()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: true);
        Assert.Equal(0, GeneratorProgram.Run([], root.Path, TextWriter.Null, TextWriter.Null, NoNetwork));
        using StringWriter output = new();
        Assert.Equal(0, GeneratorProgram.Run(["--check"], root.Path, output, TextWriter.Null, NoNetwork));
        Assert.Equal(3, output.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries).Count(line => line.EndsWith("is as generated", StringComparison.Ordinal)));

        string edited = Path.Combine(root.Path, GeneratorProgram.OutputDirectory, "UnicodeTables.Names.g.cs");
        File.WriteAllText(edited, File.ReadAllText(edited).Replace("case \"Greek\"", "case \"Gr\"", StringComparison.Ordinal));
        File.Delete(Path.Combine(root.Path, GeneratorProgram.OutputDirectory, "UnicodeTables.Folding.g.cs"));
        using StringWriter error = new();

        int exitCode = GeneratorProgram.Run(["--check"], root.Path, TextWriter.Null, error, NoNetwork);

        Assert.Equal(1, exitCode);
        string[] lines = error.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        Assert.Equal(
            [
                $"eng/unicode: {GeneratorProgram.OutputDirectory}/UnicodeTables.Folding.g.cs differs from the output of the generator; run eng/unicode without arguments and commit the result",
                $"eng/unicode: {GeneratorProgram.OutputDirectory}/UnicodeTables.Names.g.cs differs from the output of the generator; run eng/unicode without arguments and commit the result",
            ],
            lines);
    }

    [Fact]
    public static void Check_WritesNothing()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: true);

        int exitCode = GeneratorProgram.Run(["--check"], root.Path, TextWriter.Null, TextWriter.Null, NoNetwork);

        Assert.Equal(1, exitCode);
        Assert.False(Directory.Exists(Path.Combine(root.Path, GeneratorProgram.OutputDirectory)));
    }

    [Theory]
    [InlineData("--unknown")]
    [InlineData("--check --check")]
    [InlineData("check")]
    public static void AnotherInvocation_IsExitCode2WithTheUsage(string arguments)
    {
        ArgumentNullException.ThrowIfNull(arguments);
        using TempDirectory root = Excerpts.Repository(withDownloads: true);
        using StringWriter error = new();

        int exitCode = GeneratorProgram.Run(arguments.Split(' '), root.Path, TextWriter.Null, error, NoNetwork);

        Assert.Equal(2, exitCode);
        Assert.Equal("usage: eng/unicode [--check]" + Environment.NewLine, error.ToString());
    }

    [Fact]
    public static void WithTheFilesInTheDirectory_TheGeneratorNeedsNoNetwork()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: true);

        Assert.Equal(0, GeneratorProgram.Run([], root.Path, TextWriter.Null, TextWriter.Null, NoNetwork));
    }

    [Fact]
    public static void AFileThatIsNotThere_IsDownloadedOnceCheckedAndKept()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: false);
        int downloads = 0;
        Func<Uri, byte[]> download = address =>
        {
            downloads++;
            string name = address.Segments[^1];
            return Encoding.UTF8.GetBytes(Excerpts.Texts[Array.IndexOf(Excerpts.FileNames, name)]);
        };

        Assert.Equal(0, GeneratorProgram.Run([], root.Path, TextWriter.Null, TextWriter.Null, download));
        Assert.Equal(3, downloads);
        foreach (string name in Excerpts.FileNames)
        {
            Assert.True(File.Exists(Path.Combine(root.Path, GeneratorProgram.DownloadDirectory, name)));
        }

        Assert.Equal(0, GeneratorProgram.Run([], root.Path, TextWriter.Null, TextWriter.Null, NoNetwork));
    }

    [Fact]
    public static void AFileOfAnotherChecksum_IsExitCode2NamingTheFile_AndADownloadOfIt_IsNotKept()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: false);
        using StringWriter error = new();
        Func<Uri, byte[]> download = address =>
            Encoding.UTF8.GetBytes(address.Segments[^1] == "Scripts.txt" ? Excerpts.Scripts + "0042 ; Latin\n" : Excerpts.Texts[Array.IndexOf(Excerpts.FileNames, address.Segments[^1])]);

        int exitCode = GeneratorProgram.Run([], root.Path, TextWriter.Null, error, download);

        Assert.Equal(2, exitCode);
        string expected = Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(Excerpts.Scripts)));
        Assert.StartsWith("eng/unicode: Scripts.txt: the SHA-256 is ", error.ToString(), StringComparison.Ordinal);
        Assert.Contains($"inputs.txt has {expected}", error.ToString(), StringComparison.Ordinal);
        Assert.False(File.Exists(Path.Combine(root.Path, GeneratorProgram.DownloadDirectory, "Scripts.txt")));
        Assert.False(Directory.Exists(Path.Combine(root.Path, GeneratorProgram.OutputDirectory)));
    }

    [Fact]
    public static void ADownloadedFileThatIsChangedAfterwards_IsExitCode2NamingTheFile()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: true);
        root.Write(GeneratorProgram.DownloadDirectory + "/CaseFolding.txt", Excerpts.CaseFolding + "\n");
        using StringWriter error = new();

        int exitCode = GeneratorProgram.Run([], root.Path, TextWriter.Null, error, NoNetwork);

        Assert.Equal(2, exitCode);
        Assert.StartsWith("eng/unicode: CaseFolding.txt: the SHA-256 is ", error.ToString(), StringComparison.Ordinal);
    }

    [Fact]
    public static void NoInputsFile_IsExitCode2()
    {
        using TempDirectory root = new();
        using StringWriter error = new();

        int exitCode = GeneratorProgram.Run([], root.Path, TextWriter.Null, error, NoNetwork);

        Assert.Equal(2, exitCode);
        Assert.Equal($"eng/unicode: {GeneratorProgram.InputsPath} does not exist" + Environment.NewLine, error.ToString());
    }

    [Fact]
    public static void AFileOfTheFormOfAnotherVersion_IsExitCode2WithTheLine()
    {
        using TempDirectory root = Excerpts.Repository(withDownloads: false);
        string bad = Excerpts.UnicodeData + "\nXYZ;A;Lu\n";
        root.Write(GeneratorProgram.InputsPath, Excerpts.InputsText().Replace(
            Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(Excerpts.UnicodeData))),
            Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(bad))),
            StringComparison.Ordinal));
        root.Write(GeneratorProgram.DownloadDirectory + "/UnicodeData.txt", bad);
        root.Write(GeneratorProgram.DownloadDirectory + "/Scripts.txt", Excerpts.Scripts);
        root.Write(GeneratorProgram.DownloadDirectory + "/CaseFolding.txt", Excerpts.CaseFolding);
        using StringWriter error = new();

        int exitCode = GeneratorProgram.Run([], root.Path, TextWriter.Null, error, NoNetwork);

        Assert.Equal(2, exitCode);
        Assert.Matches(@"^eng/unicode: UnicodeData\.txt\(\d+\): 'XYZ' is not a code point of 4 to 6 hexadecimal digits up to 10FFFF", error.ToString());
    }

    [Fact]
    public void GeneratedFilesOfTheRepository_AreOfTheFormAndNameTheChecksumsOfInputs()
    {
        string root = RepositoryRoot.Find();
        UcdInputs inputs = UcdInputs.Parse(File.ReadAllText(Path.Combine(root, GeneratorProgram.InputsPath)));

        foreach (string name in FileNames)
        {
            string text = File.ReadAllText(Path.Combine(root, GeneratorProgram.OutputDirectory, name));
            Assert.StartsWith($"// <auto-generated>\n// Written by eng/unicode from the Unicode Character Database {inputs.Version}:\n", text, StringComparison.Ordinal);
            foreach (UcdFile input in inputs.Files)
            {
                Assert.Contains($"//   {input.Name,-16} {input.Sha256}\n", text, StringComparison.Ordinal);
            }

            Assert.DoesNotContain("\r", text, StringComparison.Ordinal);
            Assert.EndsWith("}\n", text, StringComparison.Ordinal);
            Assert.Matches(new Regex(@"^namespace Great\.Parts\.Cel\.Library\.Unicode;$", RegexOptions.Multiline), text);
        }
    }
}
